def clean(df):
    df = df.drop_duplicates(subset='penguin_id', keep='first').copy()
    df['island'] = df['island'].str.strip().replace('Bisco', 'Biscoe')
    df['sex'] = df['sex'].str.strip()
    df = df.dropna(subset=['sex'])
    return df

def answer(df):
    return df.groupby('sex')['body_mass_g'].mean().to_dict()
